import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        long n = nextLong(), m = nextLong();
        // Cycling 1..m makes every window of length <= m all-distinct and is lexicographically smallest.
        StringBuilder sb = new StringBuilder();
        for (long i = 0; i < n; i++) {
            if (i > 0) sb.append(' ');
            sb.append(i % m + 1);
        }
        System.out.println(sb);
    }
}

package main

import (
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, m := nextInt(), nextInt()
	// Cycling 1..m makes every window of length <= m all-distinct and is lexicographically smallest.
	var out []byte
	for i := int64(0); i < n; i++ {
		if i > 0 {
			out = append(out, ' ')
		}
		out = strconv.AppendInt(out, i%m+1, 10)
	}
	out = append(out, '\n')
	os.Stdout.Write(out)
}
